    setupEventListeners() {
        Object.keys(this.fields).forEach((fieldKey) => {
            const field = this.fields[fieldKey];
            field.input.addEventListener('blur', () => this.validateField(fieldKey));
            field.input.addEventListener('input', () => this.clearFieldError(fieldKey));
        });

