+class ContactFormValidator {
+    constructor(formId) {
+        this.form = document.getElementById(formId);
+        this.fields = {
+            fullName: {
+                input: document.getElementById('fullName'),
+                errorElement: document.getElementById('fullNameError'),
+                validator: this.validateFullName.bind(this),
+                required: true,
+            },
+            email: {
+                input: document.getElementById('email'),
+                errorElement: document.getElementById('emailError'),
+                validator: this.validateEmail.bind(this),
+                required: true,
+            },
+            phone: {
+                input: document.getElementById('phone'),
+                errorElement: document.getElementById('phoneError'),
+                validator: this.validatePhone.bind(this),
+                required: false,
+            },
+        };
+
+        this.successMessage = document.getElementById('successMessage');
+
+        this.setupEventListeners();
+    }
+
+    setupEventListeners() {
+        Object.keys(this.fields).forEach((fieldKey) => {
+            const field = this.fields[fieldKey];
+            field.input.addEventListener('blur', () => this.validateField(fieldKey));
+            field.input.addEventListener('input', () => this.clearFieldError(fieldKey));
+        });
+
+        this.form.addEventListener('submit', (e) => this.handleSubmit(e));
+    }
+
+    validateFullName(value) {
+        if (!value.trim()) {
+            return 'Full name is required';
+        }
+        if (value.trim().length < 2) {
+            return 'Full name must be at least 2 characters';
+        }
+        if (!/^[a-zA-Z\s'-]+$/.test(value)) {
+            return 'Full name can only contain letters, spaces, hyphens, and apostrophes';
+        }
+        return null;
+    }
+
+    validateEmail(value) {
+        if (!value.trim()) {
+            return 'Email address is required';
+        }
+        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+        if (!emailRegex.test(value)) {
+            return 'Please enter a valid email address';
+        }
+        return null;
+    }
+
+    validatePhone(value) {
+        if (!value.trim()) {
+            return null;
+        }
+        const phoneRegex = /^[\d\s\-()+.]*$/;
+        if (!phoneRegex.test(value)) {
+            return 'Phone number contains invalid characters';
+        }
+        const digitsOnly = value.replace(/\D/g, '');
+        if (digitsOnly.length > 0 && (digitsOnly.length < 10 || digitsOnly.length > 15)) {
+            return 'Phone number should contain between 10 and 15 digits';
+        }
+        return null;
+    }
+
+    validateField(fieldKey) {
+        const field = this.fields[fieldKey];
+        const value = field.input.value;
+        const error = field.validator(value);
+
+        if (error) {
+            this.showFieldError(fieldKey, error);
+            return false;
+        } else {
+            this.clearFieldError(fieldKey);
+            return true;
+        }
+    }
+
+    showFieldError(fieldKey, message) {
+        const field = this.fields[fieldKey];
+        field.input.classList.add('error');
+        field.input.classList.remove('success');
+        field.errorElement.textContent = message;
+        field.errorElement.classList.add('show');
+    }
+
+    clearFieldError(fieldKey) {
+        const field = this.fields[fieldKey];
+        const value = field.input.value;
+        const error = field.validator(value);
+
+        if (!error && (value.trim() !== '' || !field.required)) {
+            field.input.classList.remove('error');
+            field.input.classList.add('success');
+            field.errorElement.textContent = '';
+            field.errorElement.classList.remove('show');
+        } else if (error && value.trim() === '') {
+            field.input.classList.remove('error', 'success');
+            field.errorElement.textContent = '';
+            field.errorElement.classList.remove('show');
+        }
+    }
+
+    validateForm() {
+        let isValid = true;
+        Object.keys(this.fields).forEach((fieldKey) => {
+            if (!this.validateField(fieldKey)) {
+                isValid = false;
+            }
+        });
+        return isValid;
+    }
+
+    handleSubmit(e) {
+        e.preventDefault();
+
+        if (!this.validateForm()) {
+            return;
+        }
+
+        const formData = {
+            fullName: this.fields.fullName.input.value.trim(),
+            email: this.fields.email.input.value.trim(),
+            phone: this.fields.phone.input.value.trim(),
+        };
+
+        this.showSuccessMessage();
+        this.form.reset();
+        this.resetFormUI();
+    }
+
+    showSuccessMessage() {
+        this.successMessage.textContent = '✓ Your message has been sent successfully! We\'ll get back to you soon.';
+        this.successMessage.classList.add('show');
+
+        setTimeout(() => {
+            this.successMessage.classList.remove('show');
+        }, 5000);
+    }
+
+    resetFormUI() {
+        Object.keys(this.fields).forEach((fieldKey) => {
+            const field = this.fields[fieldKey];
+            field.input.classList.remove('error', 'success');
+            field.errorElement.textContent = '';
+            field.errorElement.classList.remove('show');
+        });
+    }
+}
+
+document.addEventListener('DOMContentLoaded', () => {
+    new ContactFormValidator('contactForm');
+});
+
